-- Lernfeld:1 > Das Unternehmen und die eigene Rolle im Betrieb beschreiben > Das Unternehmen > Unternehmensformen > Personengesellschaften > Offene Handelsgesellschaft
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann eine OHG von einer Person gegründet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Mindestens zwei Gesellschafter nötig"}, {"text": "Ja", "correct": false, "because": "Partnerschaft erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine OHG ins Handelsregister eingetragen werden?', 2, '[{"text": "Ja", "correct": true, "because": "HGB §105 fordert Eintragung"}, {"text": "Nein", "correct": false, "because": "Pflicht für Handelsgesellschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Haftung in einer OHG für alle Gesellschafter gleich?', 2, '[{"text": "Ja", "correct": true, "because": "Alle haften unbeschränkt"}, {"text": "Nein", "correct": false, "because": "Einheitliche Haftungsstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte eine OHG im Einzelhandel typisch sein?', 2, '[{"text": "Ja", "correct": true, "because": "Häufig in Handelsbranchen"}, {"text": "Nein", "correct": false, "because": "Nicht branchenbeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Ist die Gründung einer OHG kostspielig?', 2, '[{"text": "Nein", "correct": true, "because": "Kein Mindestkapital nötig"}, {"text": "Ja", "correct": false, "because": "Geringe Gründungskosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine OHG ohne schriftlichen Vertrag gegründet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Formfreiheit nach HGB"}, {"text": "Nein", "correct": false, "because": "Schrift nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die OHG von Vorteil, wenn ich Haftung vermeiden will?', 2, '[{"text": "Nein", "correct": true, "because": "Unbeschränkte Haftung"}, {"text": "Ja", "correct": false, "because": "Haftung ist Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte eine OHG flexibel wachsen?', 2, '[{"text": "Ja", "correct": true, "because": "Einfache Aufnahme neuer Partner"}, {"text": "Nein", "correct": false, "because": "Vorteil der Struktur"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist ein großer Nachteil einer OHG?', 2, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Persönliches Risiko"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Kein Mindestkapital"}, {"text": "Komplexe Gründung", "correct": false, "because": "Relativ einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin überlegt eine OHG zu gründen. Was ist eine rechtliche Anforderung?', 3, '[{"text": "Handelsregistereintragung", "correct": true, "because": "HGB §105"}, {"text": "Mindestkapital", "correct": false, "because": "Nicht erforderlich"}, {"text": "Genehmigung", "correct": false, "because": "Nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branche ist für eine OHG typisch?', 2, '[{"text": "Handel", "correct": true, "because": "Häufig im Einzelhandel"}, {"text": "IT-Startups", "correct": false, "because": "Eher GmbH"}, {"text": "Landwirtschaft", "correct": false, "because": "Weniger üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, wie eine OHG gegründet wird. Was sage ich?', 3, '[{"text": "Vertrag mit Partnern und Eintragung", "correct": true, "because": "Gründungsprozess"}, {"text": "Nur Vertrag", "correct": false, "because": "Eintragung fehlt"}, {"text": "Nur Kapital", "correct": false, "because": "Kein Mindestkapital"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine OHG?', 4, '[{"text": "Einfache Gründung", "correct": true, "because": "Kein Mindestkapital"}, {"text": "Flexible Führung", "correct": true, "because": "Partner entscheiden"}, {"text": "Gemeinsame Haftung", "correct": true, "because": "Risikoteilung"}, {"text": "Haftungsbegrenzung", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Anforderungen hat eine OHG?', 3, '[{"text": "Handelsregistereintrag", "correct": true, "because": "HGB §105"}, {"text": "Gesellschaftervertrag", "correct": true, "because": "Grundlage"}, {"text": "Handelsgewerbe", "correct": true, "because": "HGB Definition"}, {"text": "Mindestkapital", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir überlegen eine OHG. Welche Nachteile gibt es?', 3, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Persönliches Risiko"}, {"text": "Abhängigkeit von Partnern", "correct": true, "because": "Entscheidungen gemeinsam"}, {"text": "Haftung mit Privatvermögen", "correct": true, "because": "HGB"}, {"text": "Hohe Steuern", "correct": false, "because": "Kein direkter Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum Gründungsprozess einer OHG?', 4, '[{"text": "Gesellschaftervertrag schließen", "correct": true, "because": "Rechtliche Basis"}, {"text": "Handelsregister anmelden", "correct": true, "because": "Pflicht"}, {"text": "Gewerbeanmeldung", "correct": true, "because": "Handelsgewerbe"}, {"text": "Kapital einzahlen", "correct": false, "because": "Kein Mindestkapital"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine OHG braucht zwei Gesellschafter. b) Sie hat beschränkte Haftung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zwei ja, Haftung unbeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die OHG muss ins Handelsregister. b) Gründung ist teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Register ja, teuer nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die OHG ist im Handel typisch. b) Alle haften gleich.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Handel ja, Haftung gleich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine OHG hat einfache Gründung. b) Sie ist für Haftungsschutz ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gründung ja, Haftung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

